// Bad weather in Córdoba in the next 12 hours, from open-meteo's hourly forecast: a thunderstorm
// (with hail when its code says so), strong wind, heavy rain, extreme heat or frost. One notice per
// kind and day; a storm that turns into hail warns again. Quiet hours don't apply: hail doesn't wait.
const h = $input.first().json.hourly;
if (!h?.time) return [];
const at = (i) => Number(h.time[i].slice(11, 13));
const day = (i) => h.time[i].slice(0, 10);
const found = {};   // kind -> {from, to, peak, day}
const mark = (kind, i, value) => {
  const f = found[kind] || (found[kind] = { from: i, to: i, peak: value, day: day(i) });
  f.to = i; f.peak = Math.max(f.peak, value);
};
const num = (v) => (typeof v === 'number' ? v : null);  // a gap in the forecast is no reading (null <= 0 is true in JS)
for (let i = 0; i < h.time.length; i++) {
  const code = num(h.weather_code[i]), prob = num(h.precipitation_probability?.[i]) ?? 50;
  const gust = num(h.wind_gusts_10m[i]), rain = num(h.precipitation[i]), temp = num(h.temperature_2m[i]);
  if ((code === 96 || code === 99) && prob >= 30) mark('granizo', i, prob);
  else if (code === 95 && prob >= 40) mark('tormenta', i, prob);
  if (gust !== null && gust >= 60) mark('viento', i, gust);
  if (rain !== null && rain >= 10) mark('lluvia', i, rain);
  if (temp !== null && temp >= 38) mark('calor', i, temp);
  if (temp !== null && temp <= 0) mark('helada', i, -temp);
}
const s = $getWorkflowStaticData('global');
s.sent = s.sent || {};
for (const k of Object.keys(s.sent)) if (s.sent[k] < Date.now() - 3 * 864e5) delete s.sent[k];  // forget after 3 days
const when = (f) => {
  const a = at(f.from), b = (at(f.to) + 1) % 24;
  const today = h.time[0].slice(0, 10);
  const las = (n) => (n === 1 ? 'la 1' : `las ${n}`);
  return (f.day === today ? '' : 'mañana ') + (a === at(f.to) ? `a ${las(a)} h` : `entre ${las(a)} y ${las(b)} h`);
};
const TEXT = {
  granizo: (f) => [`Tormenta con posible granizo ${when(f)}`, `Probabilidad ${f.peak}%. Guardá el auto y lo que haya afuera.`, 'cloud_with_lightning_and_rain', 5],
  tormenta: (f) => [`Tormenta ${when(f)}`, `Probabilidad ${f.peak}%. Puede haber cortes de luz: el server aguanta con la batería.`, 'cloud_with_lightning', 4],
  viento: (f) => [`Viento fuerte ${when(f)}`, `Ráfagas de hasta ${Math.round(f.peak)} km/h.`, 'wind_face', 4],
  lluvia: (f) => [`Lluvia fuerte ${when(f)}`, `Hasta ${f.peak.toFixed(0)} mm en una hora.`, 'umbrella', 3],
  calor: (f) => [`Calor extremo ${when(f)}`, `Hasta ${Math.round(f.peak)}°.`, 'hot_face', 3],
  helada: (f) => [`Helada ${when(f)}`, `Hasta ${-Math.round(f.peak)}°. Las plantas, adentro.`, 'snowflake', 3],
};
// What's new since the last notices, worst first, in one notice. Each kind once every 12 hours: a
// storm that goes on past midnight isn't a new one.
const fresh = [];
for (const [kind, f] of Object.entries(found)) {
  if (s.sent[kind] && Date.now() - s.sent[kind] < 12 * 3600e3) continue;
  s.sent[kind] = Date.now();
  if (kind === 'tormenta' && found.granizo) continue;  // the hail line says it all
  fresh.push(TEXT[kind](f));
}
if (!fresh.length) return [];
fresh.sort((a, b) => b[3] - a[3]);
const [title, message, tag, priority] = fresh[0];
const more = fresh.slice(1).map(([t, m]) => `${t}: ${m}`);
return [{ json: { title, message: [message, ...more].join('\n'), tag, priority } }];
